module TopModule (
    input  logic       clk,
    input  logic       reset,
    input  logic [7:0] in,
    output logic       done
);

    typedef enum logic [1:0] {
        B1   = 2'd0,
        B2   = 2'd1,
        B3   = 2'd2,
        DONE = 2'd3
    } state_t;

    state_t state, next_state;

    // State transition logic
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= B1;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = state;
        case (state)
            B1: begin
                if (in[3]) begin
                    next_state = B2;
                end else begin
                    next_state = B1;
                end
            end
            B2: begin
                next_state = B3;
            end
            B3: begin
                next_state = DONE;
            end
            DONE: begin
                if (in[3]) begin
                    next_state = B2;
                end else begin
                    next_state = B1;
                end
            end
            default: begin
                next_state = B1;
            end
        endcase
    end

    // Output logic
    always_comb begin
        done = (state == DONE);
    end

endmodule

